window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1fe43c40510c033"]={"versions": [{"id": "FIG-f1fe43c40510c033", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (Schichtenarchitektur / Stack-Übersicht) im Rahmen <code>id AUTOSAR NM Stack on CAN</code>. Dargestellt ist die vertikale Schichtung des AUTOSAR Classic CAN-Netzwerkmanagement-Stacks oberhalb der Treiberebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei hierarchische Schichten mit unterstrichenen Komponenteninstanzen:</p>\n<ul class=\"fig-list\"><li>Oben: Ein generisches Netzwerkmanagement <code>:Nm</code> (grau hinterlegt, busunabhängig).\n</li><li>Mitte: Zwei parallel nebeneinander angeordnete Instanzen des busspezifischen CAN-Netzwerkmanagements <code>:CanNm</code> (beige hinterlegt).\n</li><li>Unten: Eine übergeordnete CAN-Schnittstelle <code>:CanIf</code> (beige hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Explizite Schnittstellenports oder Konnektoren sind nicht eingezeichnet; die vertikale Schichtung indiziert die Aufruf- und Abhängigkeitsrichtung zwischen den Modulen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Interaktions- oder Kontrollflusselemente. Die vertikale Anordnung impliziert den Signal- und Steuerungsfluss von der oberen Schicht (<code>:Nm</code>) über die beiden <code>:CanNm</code>-Instanzen zur CAN-Interface-Schicht (<code>:CanIf</code>) und umgekehrt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenz für die Multi-Channel- bzw. Multi-Bus-Fähigkeit des CAN-Netzwerkmanagements: Mehrere Instanzen von <code>:CanNm</code> können parallel existieren, um unterschiedliche CAN-Kanäle oder Netzwerke über eine gemeinsame <code>:Nm</code>-Koordinationsebene und das gemeinsame <code>:CanIf</code> anzusteuern.</p>"}, {"id": "FIG-f2941f959ca9222b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (Schichtenarchitektur / Stack-Übersicht) im Rahmen <code>id AUTOSAR NM Stack on CAN</code>. Dargestellt ist die vertikale Schichtung des AUTOSAR Classic CAN-Netzwerkmanagement-Stacks oberhalb der Treiberebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Drei hierarchische Schichten mit unterstrichenen Komponenteninstanzen:</p>\n<ul class=\"fig-list\"><li>Oben: Ein generisches Netzwerkmanagement <code>:Nm</code> (grau hinterlegt, busunabhängig).\n</li><li>Mitte: Eine einzelne, die gesamte Breite einnehmende Instanz des busspezifischen CAN-Netzwerkmanagements <code>:CanNm</code> (beige hinterlegt).\n</li><li>Unten: Eine CAN-Schnittstelle <code>:CanIf</code> (beige hinterlegt).\n</li></ul>\n<p class=\"fig-p\">Explizite Schnittstellenports oder Konnektoren sind nicht eingezeichnet; die vertikale Schichtung indiziert die Aufruf- und Abhängigkeitsbeziehung zwischen den Modulen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Interaktions- oder Kontrollflusselemente. Die vertikale Anordnung impliziert den Signal- und Steuerungsfluss von der oberen Schicht (<code>:Nm</code>) über die <code>:CanNm</code>-Komponente zur CAN-Interface-Schicht (<code>:CanIf</code>) und umgekehrt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Referenz für die grundlegende Schichtenbeziehung des CAN-Netzwerkmanagements im AUTOSAR-Kommunikationsstack: Dargestellt ist die 1:1:1-Schichtung zwischen <code>:Nm</code>, <code>:CanNm</code> und <code>:CanIf</code>. Multi-Channel-Kardinalitäten auf Ebene von <code>:CanNm</code> werden im Diagramm nicht mehr visuell durch parallele Komponenteninstanzen abgebildet.</p>"}], "trans": [{"from": "FIG-f1fe43c40510c033", "to": "FIG-f2941f959ca9222b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die mittlere Ebene enthält statt zweier nebeneinanderliegender <code>:CanNm</code>-Komponenteninstanzen nur noch eine einzelne, durchgehende <code>:CanNm</code>-Komponenteninstanz.\n</li></ul>"}]};
